(6572054, 978397, 53814, '<td valign="top">impressive presence, congratulations!</td>', 'impressive presence, congratulations!', '2011-10-19 23:24:31.000000', NULL, 0),
(6572183, 978477, 114969, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by LevT:</b></div><hr/><i> Christophe, congrats on another win (which to me was obvious from the start of the voting week). Oh, by the way, check out <a href="//www.smakprov.se/smakprov.php?isbn=9789163609930&amp;l=bokus" rel="nofollow" target="_blank">this</a>, you''ll be pleased. </i></td></tr></table> <br/> <br/>Thanks for the link Lev! This is an extract from the upcoming 1X "tutorial" book I believe. I knew I was featured in both the "standard" and "tutorial" 2011 books, but didn''t know which photo they chose. Happy indeed :)<br/> <br/>Oh, and congratulations to you too, I see you are on the published photographers list as well! So are <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=35720" rel="nofollow" target="_blank">Brin</a>, <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=7786" rel="nofollow" target="_blank">orvaratli</a> and <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=5112" rel="nofollow" target="_blank">ursula</a>, at least (sorry if I missed any other DPC member). Congratulations guys!<br/><br/><i>Message edited by author 2011-10-20 02:09:50.</i></td>', 'Originally posted by LevT: Christophe, congrats on another win (which to me was obvious from the start of the voting week). Oh, by the way, check out this, you''ll be pleased.   Thanks for the link Lev! This is an extract from the upcoming 1X "tutorial" book I believe. I knew I was featured in both the "standard" and "tutorial" 2011 books, but didn''t know which photo they chose. Happy indeed :) Oh, and congratulations to you too, I see you are on the published photographers list as well! So are  Brin,  orvaratli and  ursula, at least (sorry if I missed any other DPC member). Congratulations guys!', '2011-10-20 02:20:45.000000', '2011-10-20 03:09:50.000000', 0),
(6572232, 978397, 86218, '<td valign="top">Congrats on your ribbon Lev. Simple, effective with a good message and story line that can be deduced from this. Good use of depth with person in image and the figure middle center background. All works well together. Everybody else who dont think about their shots would walk right past this story and miss life.</td>', 'Congrats on your ribbon Lev. Simple, effective with a good message and story line that can be deduced from this. Good use of depth with person in image and the figure middle center background. All works well together. Everybody else who dont think about their shots would walk right past this story and miss life.', '2011-10-20 05:33:11.000000', NULL, 0),
